  "claims": [
    {
      "card_ids": ["C31", "C64", "C54", "C38", "C45", "C18", "C67", "C60", "C19"],
      "claim": "Multiple high-transfer evidence molecules show absolute oral bioavailability values clearly above 20% in healthy or normal subjects, including verapamil 22-38%, noscapine ~30%, sulpiride 27-35%, and levosulpiride 23.4-30%."
    },
    {
      "card_ids": ["C08", "C48", "C16", "C61", "C25", "C37", "C21", "C62"],
      "claim": "Additional evidence molecules also support F >= 20%: encainide 20-42%, alfentanil 23-51% under control conditions, valbenazine ~49%, colchicine mean 55%, and codeine 40-90%."
    },
    {
      "card_ids": ["C22", "C44", "C28", "C17", "C71"],
      "claim": "Low numeric bioavailability values are confined to altered conditions such as rifampin coadministration for alfentanil (4-9%) or borderline verapamil values (18-20%, 19.4%), which are less transferable and do not outweigh the consistent ordinary-condition measurements."
    },
    {
      "card_ids": ["C13", "C65", "C39", "C29", "C52"],
      "claim": "Qualitative descriptions of 'low' or 'poor' bioavailability lack threshold-specific numeric support and are not treated as affirmative evidence for F < 20%."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": ["C17", "C71", "C22", "C44", "C28"],
  "decision_summary": "All transferred evidence molecules have absolute oral bioavailability predominantly >=20% in ordinary conditions; low values are confined to altered conditions or qualitative descriptions, so the prediction is high.",
  "evidence_gaps": [
    "Some evidence molecules have values near the 20% threshold (verapamil 18-20%, 19.4%) or broad ranges (codeine 15-80%), adding minor threshold uncertainty.",
    "Low values observed under altered conditions (rifampin coadministration, hepatic cirrhosis) are not directly transferable to ordinary conditions."
